    ∃ r > 0, closedBall z₀ r ⊆ Ω ∧ ∀ z ∈ sphere z₀ r, g z ≠ 0

lemma hyperbolicDist_eq_zero_iff_of_mem_ball {z w : ℂ}
    (hz : z ∈ ball (0 : ℂ) 1) (hw : w ∈ ball (0 : ℂ) 1) :
