theorem schwarzReflection_def (f : ℂ → ℂ) (z : ℂ) :
    schwarzReflection f z =
      if 0 ≤ z.im then f z else (starRingEnd ℂ) (f ((starRingEnd ℂ) z))

lemma image_conj_inter_im_pos_of_symmetric {Ω : Set ℂ}
