theorem HasCauchyPVWith.sub_right {γ : ℝ → ℂ} {a b c : ℝ} {f : ℂ → ℂ} {S : Finset ℂ} {L L₂ : ℂ}
    (h_ac : HasCauchyPVWith γ a c f S L) (h_bc : HasCauchyPVWith γ b c f S L₂) :
